902	impl<T: Fold> Fold for Option<T> {
903	    fn fold(self, outer: Self) -> Self {
904	        match (self, outer) {
905	            (Some(inner), Some(outer)) => Some(inner.fold(outer)),
906	            // An explicit `None` should be respected, thus we don't do
907	            // `inner.or(outer)`.
908	            (inner, _) => inner,
909	        }
910	    }
911	}
